const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) {
            return null;
        }
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const A = nextInt();
    if (A === null) return;
    const L = nextInt();
    const N = nextInt();

    let bestId = -1;
    let minArea = Infinity;

    for (let i = 1; i <= N; i++) {
        const X = nextInt();
        const Y = nextInt();

        const fitsNormal = (A <= X && L <= Y);
        const fitsRotated = (A <= Y && L <= X);

        if (fitsNormal || fitsRotated) {
            const area = X * Y;
            if (area < minArea) {
                minArea = area;
                bestId = i;
            }
        }
    }

    console.log(bestId);
}

main();
